class AsyncReportsApi(AsyncKonApi):
    """kon-reports

    Aggregate queries over kon tables and datasets, saved reports, kon-shipped reports and dashboards.
    """

    kon = "kon-reports"

    async def aggregate(self, *, body: AggregateBody, request_options: Optional[RequestOptions] = None) -> Outcome[AggregateResult]:
        """Run an aggregate query

        Computes count, count_distinct, sum, avg, min or max over a table an installed kon declares, or over a dataset, optionally grouped (with day/week/month/quarter/year buckets for dates) and filtered. Runs as you: row policies decide which rows are counted. Columns that hold secrets are refused. Returns one row per group, at most `limit` (default 100, max 1000); `truncated` says there were more.

        REST: `POST /api/reports/aggregate` · scope `kon:reports:aggregate`
        not idempotent (an Idempotency-Key is sent automatically) · MCP tool `reports_aggregate`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["aggregate"], {}, body, request_options)

    async def create_dashboard(self, *, body: CreateDashboardBody, request_options: Optional[RequestOptions] = None) -> Outcome[CreateDashboardResult]:
        """Create a dashboard

        An ordered list of tiles. Each tile names a report (a saved report's id, or `kon:<kon id>/<report id>`), with an optional title and a width from 1 to 12.

        REST: `POST /api/reports/dashboards` · scope `kon:reports:create-dashboard`
        not idempotent (an Idempotency-Key is sent automatically)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["create-dashboard"], {}, body, request_options)

    async def create_report(self, *, body: CreateReportBody, request_options: Optional[RequestOptions] = None) -> Outcome[CreateReportResult]:
        """Save a report

        Stores an aggregate query under a name, with an optional chart hint (`type`: table, number, bar, line, donut; `x`; `y`). The query is checked against the real tables first: a report that could not run is not saved.

        REST: `POST /api/reports` · scope `kon:reports:create-report`
        not idempotent (an Idempotency-Key is sent automatically)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["create-report"], {}, body, request_options)

    async def delete_dashboard(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[DeleteDashboardResult]:
        """Delete a dashboard

        Deletes the dashboard. Its reports are kept.

        REST: `DELETE /api/reports/dashboards/{id}` · scope `kon:reports:delete-dashboard`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["delete-dashboard"], {"id": id}, None, request_options)

    async def delete_report(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[DeleteReportResult]:
        """Delete a saved report

        Deletes the report. A dashboard tile that pointed at it shows that the report is gone.

        REST: `DELETE /api/reports/{id}` · scope `kon:reports:delete-report`
        idempotent (safe to retry) · sensitive: may come back as a proposal pending human approval
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_IDEMPOTENCY_KEY_REUSED`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["delete-report"], {"id": id}, None, request_options)

    async def get_dashboard(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[GetDashboardResult]:
        """Read a dashboard

        One dashboard with its tiles.

        REST: `GET /api/reports/dashboards/{id}` · scope `kon:reports:get-dashboard`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["get-dashboard"], {"id": id}, None, request_options)

    async def get_report(self, *, id: Union[str, int], request_options: Optional[RequestOptions] = None) -> Outcome[GetReportResult]:
        """Read a saved report

        One saved report with its query and chart hint. Kon reports are read from list-reports.

        REST: `GET /api/reports/{id}` · scope `kon:reports:get-report`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_NOT_FOUND`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`
        """
        return await self._call(OPERATIONS["get-report"], {"id": id}, None, request_options)

    async def list_dashboards(self, *, limit: Optional[int] = None, offset: Optional[int] = None, request_options: Optional[RequestOptions] = None) -> Outcome[ListDashboardsResult]:
        """List dashboards

        Every dashboard with its tiles. Each tile points at a report; run them with run-dashboard.

        REST: `GET /api/reports/dashboards` · scope `kon:reports:list-dashboards`
        idempotent (safe to retry)
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            limit: Rows per page (1-200). The default is the maximum, what the list always returned.
            offset: Rows to skip.
        """
        return await self._call(OPERATIONS["list-dashboards"], {"limit": limit, "offset": offset}, None, request_options)

    def iter_list_dashboards(self, *, limit: Optional[int] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[CreateDashboardResponseDashboard]:
        """Every item of `list_dashboards`, page after page (moves `offset`).

        Stops on an empty or short page, or when the response says there is no more. Raises `ProposalPendingError` if a page needs human approval.
        """
        return self._iterate(OPERATIONS["list-dashboards"], {"limit": limit}, request_options)

    async def list_reports(self, *, limit: Optional[int] = None, offset: Optional[int] = None, request_options: Optional[RequestOptions] = None) -> Outcome[ListReportsResult]:
        """List reports

        The reports people saved (`source: saved`) and the ones installed kons ship (`source: kon`, read-only, id `kon:<kon id>/<report id>`), each with its query.

        REST: `GET /api/reports` · scope `kon:reports:list-reports`
        idempotent (safe to retry) · MCP tool `reports_list`
        Errors: `KITSUDEN_E_VALIDATION`, `KITSUDEN_E_BAD_REQUEST`, `KITSUDEN_E_UNAUTHENTICATED`, `KITSUDEN_E_FORBIDDEN`, `KITSUDEN_E_RATE_LIMITED`, `KITSUDEN_E_INTERNAL`

        Args:
            limit: Rows per page (1-500). The default is the maximum, what the list always returned.
            offset: Rows to skip.
        """
        return await self._call(OPERATIONS["list-reports"], {"limit": limit, "offset": offset}, None, request_options)

    def iter_list_reports(self, *, limit: Optional[int] = None, request_options: Optional[RequestOptions] = None) -> AsyncIterator[CreateReportResponseReport]:
        """Every item of `list_reports`, page after page (moves `offset`).

        Stops on an empty or short page, or when the response says there is no more. Raises `ProposalPendingError` if a page needs human approval.
        """
        return self._iterate(OPERATIONS["list-reports"], {"limit": limit}, request_options)

